trigger OpportunityTrigger on Opportunity__c (before insert, before update, after update) {
    if (Trigger.isBefore) {
        OpportunityStageProbabilityService.syncProbability(Trigger.new, Trigger.oldMap);
        OpportunityCsStageService.initializeCsStage(Trigger.new);
    }
    if (Trigger.isAfter && Trigger.isUpdate) {
        ContractOppClassificationSyncService.syncFromOpportunityUpdates(
            Trigger.new,
            Trigger.oldMap
        );
    }
}

trigger QuotationLineTrigger on QuotationLine__c (
    before insert,
    before update,
    after insert,
    after update,
    after delete,
    after undelete
) {
    if (Trigger.isBefore) {
        ProductUnitPriceSyncService.syncQuotationLineUnitPrice(Trigger.new, Trigger.oldMap);
    }

    if (Trigger.isAfter) {
        OpportunityMrrSyncService.syncFromQuotationLines(Trigger.new, Trigger.old);
    }
}

trigger QuotationTrigger on Quotation__c (after insert, after update, after delete, after undelete) {
    OpportunityMrrSyncService.syncFromQuotations(Trigger.new, Trigger.old);
}

trigger ContractTrigger on Contract__c (after insert, after update) {
    ContractMonthlyLineBatch.createInitialLinesForActivatedContracts(
        Trigger.new,
        Trigger.isUpdate ? Trigger.oldMap : null
    );
}

trigger ContractLineItemTrigger on ContractLineItem__c (before insert, before update) {
    ContractLineItemPeriodService.populatePeriodFields(Trigger.new);
}
